@torch.no_grad()
def filter_mem_batch_greedy(cl_memory: torch.Tensor, batch: torch.Tensor, r: float = 0.3) -> torch.Tensor:
    """Walking the batch in order, a point is kept only if it is not already covered - neither within
    cl_memory (UoB^{t}) or within the already accepted points in this batch (dUoB^(t))."""
    m = batch.shape[0]
    if m > 0 and len(cl_memory) > 0: # cull against the existing cl_memory
        covered = is_in_union_of_balls(cl_memory, batch, r=r).squeeze(1).bool()  # (m,)
        cand = batch[~covered]
    else:
        cand = batch  # cand might be empty here - yet we still need to run the whole func otherwise DDP deadlocks.

    # Greedy filtering over the batch's candidate set . The loop is inherently serial:
    # running it on the GPU means a CPU<->GPU round-trip per iteration (pure launch
    # latency). Instead move the candidate distance block to CPU once (should be small) and loop in numpy.
    def _greedy(c: torch.Tensor) -> torch.Tensor:
        k = c.shape[0]
        if k == 0:
            return c
        close = (torch.cdist(c.float(), c.float()) <= r).cpu().numpy()  # (k, k) bool, one transfer
        keep = np.zeros(k, dtype=bool)
        for i in range(k):
            if not (close[i, :i] & keep[:i]).any():  # not within r of an earlier accepted candidate
                keep[i] = True
        return c[torch.from_numpy(keep).to(c.device)]

    if not (dist.is_initialized() and dist.get_world_size() > 1):
        return _greedy(cand)

    # DDP: gather candidates and let rank 0 filter within the batch. Then broadcast so every rank can update cl_memory with dUoB^{t}.
    union = all_gather_var(cand)                                   # identical on all ranks
    dUoB = _greedy(union) if dist.get_rank() == 0 else None
    dUoB = broadcast_var(dUoB, feat=batch.shape[1], dtype=batch.dtype, src=0, device=batch.device)
    return dUoB


def is_in_union_of_balls(cl_memory: torch.Tensor, new_samples: torch.Tensor, r: float = 0.3, chunk_n: int = 131072, chunk_m: int = 8192) -> torch.Tensor:
    m = new_samples.shape[0]
    if len(cl_memory) == 0:
        return torch.zeros([m, 1], dtype=torch.int32, device=new_samples.device)

    # Tile over both new_samples (m) and cl_memory (n) so we never materialize the full (n, m) distance matrix
    n = cl_memory.shape[0]
    min_dists = torch.full((m,), float("inf"), device=new_samples.device)
    for s in range(0, m, chunk_m):
        q = new_samples[s:s + chunk_m].float()                      # (c, d) -- only this tile upcast
        for t in range(0, n, chunk_n):
            d = torch.cdist(cl_memory[t:t + chunk_n].float(), q)    # (n_chunk, c) -- only this tile upcast
            min_dists[s:s + chunk_m] = torch.minimum(min_dists[s:s + chunk_m], d.min(dim=0).values)
    return (min_dists <= r).to(torch.int32).unsqueeze(dim=1)


def set_shared_prefix_ids(model: nn.Module, tokenizer) -> None:
    """Cache the chat template's shared-prefix token ids on the model.

    Call once after loading. Until it is called (or if the tokenizer has no chat template) the prefix is
    empty, so nothing is held out and every real token counts -- the pre-existing behaviour.
    """
    from cl_memory import shared_prefix_ids
    inner = model.module if hasattr(model, "module") else model
    inner.model._shared_prefix_ids = shared_prefix_ids(tokenizer)


def set_shared_prefix_mask(backbone: nn.Module, input_ids: torch.Tensor, token_pad_mask: torch.Tensor) -> None:
    """Publish this batch's shared-prefix mask to every wrapped linear (see ConditionalLoRALinear.prefix_mask)."""
    from cl_memory import drop_shared_prefix_mask
    prefix_ids = getattr(backbone, "_shared_prefix_ids", None)
    if prefix_ids is None or prefix_ids.numel() == 0:
        return
    mask = drop_shared_prefix_mask(input_ids, token_pad_mask, prefix_ids.to(input_ids.device))
    for module in backbone.modules():
        if isinstance(module, ConditionalLoRALinear):
            module.prefix_mask = mask


def _proj(layer: nn.Module, x: torch.Tensor, token_pad_mask: Optional[torch.Tensor]) -> torch.Tensor:
    """Call a projection, forwarding token_pad_mask only to wrapped CL linears
    (a plain nn.Linear has no such arg)."""
    if isinstance(layer, ConditionalLoRALinear):
        return layer(x, token_pad_mask)
    return layer(x)


class ConditionalLoRALinear(nn.Module):
    """A frozen ``nn.Linear`` with K conditional low-rank adapters.

    For each LoRA i with condition ``cond_i``, we evaluate a per-token boolean
    mask ``cond_i(x) -> [batch, seq]`` and add ``scaling_i * B_i(A_i(x))`` to the
    base output for exactly the tokens where the condition is true. Updates from
    all active LoRAs are summed:

        out = base(x) + Σ_i  mask_i * scaling_i * B_i(A_i(x))

    K can grow at runtime via :meth:`add_lora`. The base weight/bias are frozen;
    only the LoRA parameters train. Each LoRA's ``B`` starts at zero, so adding a
    new LoRA leaves the model output unchanged until it's trained.
    """

    def __init__(self, base: nn.Linear, is_cl_lora: bool = False, cl_memory_type: str = "uob", smoothing_alpha: float = 1.0):
        super().__init__()
        self.base = base
        self.base.weight.requires_grad_(False)
        if self.base.bias is not None:
            self.base.bias.requires_grad_(False)

        # K parallel adapters, grown over time. Parameters live in ParameterLists
        # so they register with the model (state_dict, .parameters(), DDP) correctly.
        self.lora_A = nn.ParameterList()
        self.lora_B = nn.ParameterList()
        self.scalings: list[float] = []

        # CL
        self.is_cl_lora: bool = is_cl_lora # When False, behaves as a plain LoRA
        self.cl_memory_type: str = cl_memory_type # 'uob' / 'gmm'
        self.cl_memory: list[torch.Tensor] = []
        self.cl_rad: list[float] = []
        self.cl_gmm: list = []
        self._pending_x: list[torch.Tensor] = [] # Inputs the layer saw since the last optimizer step, buffered so the active LoRA's cl_memory can be grown at step time
        self.is_cl_accum: bool = False # Whether the model is in accumulation state. This means that forward buffers its inputs for cl_memory accumulation. Off by default; the training loop turns it on (alongside model.train())
        self.accum_lora_idx: int = -1 # Index of the LoRA currently accumulating cl_memory (the one being trained now).
        self.is_cl_memory_owner: bool = True # Sharing cl memory buffers: {Wq,Wk,Wv} and {up_proj,gate_proj} see identical input (respectively).
                                             # apply_conditional_lora_wrapper aliases cl_memory/cl_rad to one owner (Wq and gate_proj). Both owner and siblings can READ, but only the owner WRITES.
                                             # _pending_x is NOT shared: only the owner ever buffers into it (siblings return early in forward), so each sibling just keeps its own empty list.
        self.jl_P: Optional[torch.Tensor] = None # JL projection: inputs are projected to k<<D dims before being stored/gated.
                                                 # None = off (store full D). JL preserves distances, so cl_rad is unchanged. Siblings alias the owner's jl_P.
        self.is_disabled: list[bool] = [] # PER PHASE: one entry per adapter, appended by add_lora. Set when phase i's GMM
                                       # fit fails (see cl_memory.fit_layer_gmms) -- that phase's gate is untrustworthy, so
                                       # adapter i alone is skipped in the forward, while earlier phases' adapters (already
                                       # trained, with working gates) keep firing. A single bool here would let a late-phase
                                       # fit failure silently switch off every previously learned adapter in the module.
                                       # Siblings alias the owner's list (see _link_shared_cl_memory).
        
        # CL - hit rate tracking: counts gating decisions during a forward, so gmm_eval can read off
        # the fraction of tokens this LoRA fires on. Off by default (adds a sync per gated module).
        self.is_hit_rate_tracking: bool = False
        self.hit_count: int = 0
        self.token_count: int = 0
        self.seq_hit_count: int = 0  # sequences with >=1 gated token (see the tracking block in forward)
        self.seq_count: int = 0
        # Optional [B, T] bool that excludes the chat template's shared prefix (excludes padding as well). That prefix is
        # identical in every templated sample, so the gate fires on it whatever the content -- harmless in
        # itself (it is in every sequence, so there is no capability there to disturb) but it inflates the
        # hit rate, and smoothing over it would seed every sequence with the same constant. Set per batch
        # by the caller (see cl_memory.drop_shared_prefix_mask); None = fall back to the pad mask alone.
        self.prefix_mask: Optional[torch.Tensor] = None

        # Temporal smoothing of the gating decision during inference (see _temporal_smoothing_filter).
        self.smoothing_alpha: float = smoothing_alpha
        self._smoothing_state: dict = {}  # {adapter_idx: [B] running value}, carried across incremental decode steps

        # CL - Compaction diagnostics (UoB)
        self.compact_step_seen: int = 0   # points the current iteration considered
        self.compact_step_kept: int = 0   # points the current iteration added
        self.compact_total_seen: int = 0  # cumulative considered
        self.compact_total_kept: int = 0  # cumulative added

    @property
    def num_loras(self) -> int:
        return len(self.lora_A)

    def add_lora(self, r: int, alpha: float, cl_rad: float = 0.3, gmm_kwargs: Optional[dict] = None,
                 is_disabled: bool = False) -> int:
        """Append a new conditional LoRA. The LoRA is gated per-token by ball membership
        All previously added LoRAs are frozen (``requires_grad=False``), so only
        the newest one trains -- e.g. add one per continual-learning task and the
        earlier tasks' adapters stay fixed.

        ``is_disabled`` marks this phase as disabled from the start -- used when the module's negative GMM
        was never successfully fitted, so no phase of it can ever gate (the negative is fitted once, on
        phase 0, and never refitted). Such an adapter is appended frozen so it cannot train either:
        otherwise it would learn ungated as the accumulating phase and then sit inert at inference.
        """
        if r <= 0:
            raise ValueError(f"LoRA rank must be positive, got {r}")
        for p in self.lora_A:
            p.requires_grad_(False)
        for p in self.lora_B:
            p.requires_grad_(False)
        factory_kwargs = {"device": self.base.weight.device, "dtype": self.base.weight.dtype}
        A = nn.Parameter(torch.empty(r, self.base.in_features, **factory_kwargs))
        B = nn.Parameter(torch.zeros(self.base.out_features, r, **factory_kwargs))
        nn.init.kaiming_uniform_(A, a=math.sqrt(5))
        if is_disabled: # disabled module: append but keep frozen -> fully inert (B=0, never trains)
            A.requires_grad_(False)  # per-module: siblings alias is_disabled but own their A/B
            B.requires_grad_(False)
        self.lora_A.append(A)
        self.lora_B.append(B)
        self.scalings.append(alpha / r)
        if self.is_cl_memory_owner: # only the owner materializes the buffer
            # Normally a phase starts enabled and a failed POSITIVE fit flips its entry later (see
            # cl_memory.fit_layer_gmms); a failed negative fit disables it on arrival, as above.
            # Owner-only, like cl_memory/cl_rad below: siblings alias the owner's list, so a sibling append
            # would grow the shared list once per group member and desync it from the adapter indices.
            self.is_disabled.append(is_disabled)
            mem_dim = self.jl_P.shape[1] if self.jl_P is not None else self.base.in_features  # k if JL on, else D
            self.cl_memory.append(torch.empty(0, mem_dim, device=self.base.weight.device, dtype=torch.bfloat16)) # bf16; cdist upcasts to fp32.
            self.cl_rad.append(cl_rad)
            if self.cl_memory_type == "gmm":
                clf = GMMClassifierGPU(**gmm_kwargs, device=self.base.weight.device)
                if self.cl_gmm:  # reuse negative GMM if exists
                    clf.neg_gmm = self.cl_gmm[0].neg_gmm
                    # Carry the vectorized params too, not just the pomegranate object: predict() reads
                    # params_vectorized, and is_fitted is defined off it. A fresh instance starts with
                    # {"pos": None, "neg": None}, and nothing refits the negative for a later phase (it is
                    # fitted once on phase 0), so without this the phase would report is_fitted == False
                    # and is_in_gmm would return all-zeros -- the LoRA would never gate.
                    clf.params_vectorized["neg"] = self.cl_gmm[0].params_vectorized["neg"]
                self.cl_gmm.append(clf)
        self.accum_lora_idx = self.num_loras - 1  # the new LoRA is the one now training
        return self.accum_lora_idx

    @torch.no_grad()
    def update_cl_memory(self) -> None:
        """
        Flush buffered inputs into the accumulating LoRA's `cl_memory`.
        Call once at optimizer-step time.
        """
        if not self.is_cl_memory_owner: # only owners update the buffer
            return
        self.compact_step_seen = 0
        self.compact_step_kept = 0
        if self.is_cl_accum and self.accum_lora_idx >= 0 and self._pending_x:
            idx = self.accum_lora_idx
            flat = torch.vstack(self._pending_x).to(self.cl_memory[idx].dtype)
            seen = flat.shape[0]
            flat = filter_mem_batch_greedy(self.cl_memory[idx], flat, r=self.cl_rad[idx])
            self.cl_memory[idx] = torch.vstack([self.cl_memory[idx], flat])
            if dist.is_initialized():  # `kept` is global as-is (flat is synced between ranks) - no need to reduce
                t = torch.tensor(seen, device=flat.device)
                dist.all_reduce(t, op=dist.ReduceOp.SUM)
                seen = int(t.item())
            self.compact_step_seen = seen
            self.compact_step_kept = flat.shape[0]
            self.compact_total_seen += seen
            self.compact_total_kept += flat.shape[0]
        self._pending_x = []

    @torch.no_grad()
    def flush_cl_memory(self) -> None:
        """Empty the accumulating LoRA's `cl_memory` (and drop any pending inputs).
        Used in multi-epoch training (epoch rebuilds the volume over the updated data representation).
        Also resets the compaction diagnostics."""
        if not self.is_cl_memory_owner:  # only owners hold the buffer / counters (siblings alias/never write)
            return
        self._pending_x = []
        self.compact_step_seen = self.compact_step_kept = 0
        self.compact_total_seen = self.compact_total_kept = 0
        if self.accum_lora_idx < 0:
            return
        idx = self.accum_lora_idx
        mem = self.cl_memory[idx]
        self.cl_memory[idx] = torch.empty(0, mem.shape[1], device=mem.device, dtype=mem.dtype)
        if self.cl_memory_type == "gmm":  # drop the positive gmm so the next epoch rebuilds it
            self.cl_gmm[idx].reset_pos()

    def is_in_cl_memory(self, i: int, flat_jl: torch.Tensor) -> torch.Tensor:
        if self.cl_memory_type == "gmm":
            return is_in_gmm(self.cl_gmm[i], flat_jl)
        return is_in_union_of_balls(self.cl_memory[i], flat_jl, r=self.cl_rad[i])

    def _temporal_smoothing_filter(self, mask: torch.Tensor, i: int, token_pad_mask: Optional[torch.Tensor]) -> torch.Tensor:
        """Smooth the per-token gating decision over neighbouring tokens (inference only).

            s_t = alpha * mask_t + (1 - alpha) * s_(t-1)   ->   gate on  s_t > 0.5

        The gate decides each token independently, so one out-of-task token that happens to look in-task
        opens it for a single position. Smoothing damps those isolated spikes while leaving genuine
        in-task runs open (it even fills single-token gaps inside them).

        Inactive positions -- left padding, and the chat template's shared prefix (identical in every
        sample, so smoothing over it would seed every sequence with the same constant) -- are held out:
        the running value is carried past them unchanged, and they keep their raw decision.

        Causal, so the filter behaves the same during generation. A full (T > 1) forward is a new
        sequence and starts from zero; T == 1 steps are incremental decoding and continue from the state
        that forward left behind. (Beam search / multi-sample decoding reorder the batch between steps
        and are not handled.)
        """
        alpha = self.smoothing_alpha
        m = mask.to(torch.float32)
        active = token_pad_mask.bool() if token_pad_mask is not None else torch.ones_like(mask)
        # prefix_mask is built for a full forward, so it only lines up with mask when T > 1; a generated token is never part of the prompt's prefix anyway.
        if self.prefix_mask is not None and mask.shape[1] > 1:
            active = active & self.prefix_mask.to(mask.device)

        if m.shape[1] == 1:  # incremental decoding: continue from the prefill forward that preceded it
            self._smoothing_state[i] = torch.where(active[:, 0], alpha * m[:, 0] + (1 - alpha) * self._smoothing_state[i], self._smoothing_state[i])
            return torch.where(active[:, 0], self._smoothing_state[i] > 0.5, mask[:, 0]).unsqueeze(1) # return unsmoothed value for prefix tokens

        s = torch.zeros_like(m[:, 0])  # new sequence
        out = torch.empty_like(m)
        for t in range(m.shape[1]):
            # Only active positions advance the running value; elsewhere it is carried through untouched.
            s = torch.where(active[:, t], alpha * m[:, t] + (1 - alpha) * s, s)
            out[:, t] = s
        self._smoothing_state[i] = s  # a following incremental decode picks up where this left off
        return torch.where(active, out > 0.5, mask) # return unsmoothed value for prefix tokens

    def forward(self, x: torch.Tensor, token_pad_mask: Optional[torch.Tensor] = None) -> torch.Tensor:
        '''
        Explanation for torch.no_grad() on the UoB computation (or is_in_gmm):
        The grad of a product y = f(x) ⊙ x is dy/dx = df(x)/dx ⊙ x + f(x) ⊙ 1
        In our case f(x) = UoB(x), which has an expensive gradient because of cdist. However, the gradient of UoB(x) is 0 almost everywhere so we can avoid computing it.
        (if x is inside/outside of the volume, a small neighbourhood is also inside/outside of the volume, respectively, so theres no change.
        This is not true when x is on the border of the volume - then the grad is a delta - but we can ignore these cases - just like the max-pooling grad).
        So all in all, we get an equivalent gradient when treating UoB(x) as a constant: y = UoB(x.detach()) ⊙ x -> dy/dx = UoB(x) ⊙ 1 - with the benefit of not calling autograd on cdist.
        '''
        out = self.base(x)

        if not self.is_cl_lora:  # plain LoRA: every adapter always-active, no gating/buffering
            for lora_A, lora_B, scaling in zip(self.lora_A, self.lora_B, self.scalings):
                out = out + scaling * F.linear(F.linear(x, lora_A), lora_B)  # (B,T,D)
            return out

        B, T = x.shape[:2]
        flat = x.reshape(B * T, x.shape[-1])  # (B*T, D)
        # bf16 projection is fine - the matmul accumulates in fp32 and JL's own eps dwarfs the input rounding
        flat_jl = flat @ self.jl_P.to(flat.dtype) if self.jl_P is not None else flat  # (B*T, k) or (B*T, D)
        if self.is_cl_accum and self.is_cl_memory_owner: # only owners update the buffer
            if token_pad_mask is not None:
                keep = token_pad_mask.reshape(B * T).bool()  # (B*T,) True = real token
                self._pending_x.append(flat_jl[keep].detach().to(torch.bfloat16))
            else:
                self._pending_x.append(flat_jl.detach().to(torch.bfloat16))

        for i, (lora_A, lora_B, scaling) in enumerate(zip(self.lora_A, self.lora_B, self.scalings)):
            if self.is_disabled[i]:  # this phase's GMM fit failed -> skip it; other phases keep gating
                continue
            # During training the data is in-distribution -> gate for last lora should be open.
            if self.training and i == self.accum_lora_idx:
                out = out + scaling * F.linear(F.linear(x, lora_A), lora_B)  # (B,T,D)
                continue

            with torch.no_grad(): # see explanation in function description
                mask = self.is_in_cl_memory(i, flat_jl)

            mask = mask.bool().reshape(B, T)  # [B, T], one decision per token
            if not self.training and self.smoothing_alpha < 1.0: # smoothing is applied only during inference - otherwise the data is in-distribution (training)
                mask = self._temporal_smoothing_filter(mask, i, token_pad_mask) 
            # if self.prefix_mask is not None and mask.shape[1] > 1: # Force the chat template's shared prefix closed
            #     mask = mask & self.prefix_mask.to(mask.device)
            if self.is_hit_rate_tracking:  # fraction of tokens this LoRA fires on (see gmm_eval)
                keep = token_pad_mask.bool() if token_pad_mask is not None else torch.ones_like(mask)
                if self.prefix_mask is not None and mask.shape[1] > 1:  # drop the template's shared prefix from the count (see _temporal_smoothing_filter on the T > 1 guard)
                    keep = keep & self.prefix_mask.to(mask.device)
                hits = mask & keep
                self.hit_count += int(hits.sum())
                self.token_count += int(keep.sum())
                self.seq_hit_count += int(hits.any(dim=1).sum())
                self.seq_count += int(keep.any(dim=1).sum())  # rows that are entirely padding/prefix don't count
            x_masked = x * mask.unsqueeze(-1).to(x.dtype)  # gate the input: out-of-ball tokens -> 0
            update = scaling * F.linear(F.linear(x_masked, lora_A), lora_B)  # (B,T,D)
            out = out + update
        
        return out


LORA_DEFAULT_TARGET_MODULES = ("q_proj", "k_proj", "v_proj", "o_proj", "gate_proj", "up_proj", "down_proj")


def apply_conditional_lora_wrapper(
    model: nn.Module,
    target_modules: tuple = LORA_DEFAULT_TARGET_MODULES,
    is_cl_lora: bool = False,
    jl_k: int = 0,
    jl_seed: int = 0,
    calib_rad_path: str = "",
    cl_memory_type: str = "uob",
    smoothing_alpha: float = 1.0,
) -> nn.Module:
    """Freeze the base model and wrap targeted ``nn.Linear`` layers in
    ``ConditionalLoRALinear`` in place (K=0 -- no adapters yet). Returns the same
    model with all base parameters frozen. Grow K by calling :func:`add_lora`
    (e.g. once per continual-learning task).

    ``jl_k`` > 0 enables JL compression: each wrapped module gets a fixed (D, k) Gaussian projection, so cl_memory stores k-dim points instead of D-dim.
    JL preserves distances, so cl_rad is unchanged. The projection is seeded deterministically (jl_seed + a
    per-module index) so every DDP rank builds the identical matrix.

    ``calib_rad_path``: optional path to a JSON calibration file ({layer: {module: r}}).
    If provided, sets _calib_rad on each owner so add_lora() uses per-layer radii. Ignored unless
    ``cl_memory_type`` is "uob" -- the radii mean nothing to the gmm backend."""
    for p in model.parameters():
        p.requires_grad_(False)

    # Collect first so we don't mutate the module tree while iterating it.
    to_replace = [
        (name, module)
        for name, module in model.named_modules()
        if isinstance(module, nn.Linear) and name.rsplit(".", 1)[-1] in target_modules
    ]
    for name, module in to_replace:
        parent_name, _, child_name = name.rpartition(".")
        parent = model.get_submodule(parent_name) if parent_name else model
        setattr(parent, child_name, ConditionalLoRALinear(module, is_cl_lora=is_cl_lora, cl_memory_type=cl_memory_type, smoothing_alpha=smoothing_alpha))

    if calib_rad_path and cl_memory_type == "uob":  # before linking, so siblings inherit the owner's is_disabled / _calib_rad
        import json
        with open(calib_rad_path) as f:
            calib = json.load(f)
        load_cl_rad_calibration(model, calib)

    if jl_k > 0:
        _build_jl_projections(model, jl_k, jl_seed)
    _link_shared_cl_memory(model)

    set_cl_flag(model, "is_cl_lora", is_cl_lora)  # toggles whether we use the cl method or not
    set_cl_flag(model, "is_cl_accum", False)      # single source of truth for the accum state (queryable/restorable)
    set_cl_flag(model, "cl_memory_type", cl_memory_type)

    return model


CL_MEMORY_NON_OWNERS = ("k_proj", "v_proj", "up_proj")  # share an owner's cl_memory -> skip; they get the owner's jl_P when linking

def _build_jl_projections(model: nn.Module, k: int, seed: int) -> None:
    """Give each cl_memory owner a fixed (D, k) JL projection: Gaussian entries scaled by 1/sqrt(k)
    so the projection is distance-preserving in expectation. Non-owners (k/v/up_proj) are skipped --
    they pick up the owner's jl_P during linking. Seeded per-owner (seed + index) on CPU so every DDP
    rank produces the identical matrix, then moved to the module's device/dtype."""
    idx = 0
    for name, module in model.named_modules():
        if not isinstance(module, ConditionalLoRALinear) or name.rsplit(".", 1)[-1] in CL_MEMORY_NON_OWNERS:
            continue
        D = module.base.in_features
        gen = torch.Generator().manual_seed(seed + idx)  # CPU generator -> identical on all ranks
        P = torch.randn(D, k, generator=gen) / math.sqrt(k)
        module.jl_P = P.to(device=module.base.weight.device, dtype=module.base.weight.dtype)
        idx += 1


def _link_shared_cl_memory(model: nn.Module) -> None:
    """Share cl_memory within each group that sees identical input: {Wq,Wk,Wv} and {gate_proj,up_proj}.
    The first module is the owner (Wq, gate_proj), and the others only have read access."""
    def link(owner, siblings):
        if not isinstance(owner, ConditionalLoRALinear):
            return
        for s in siblings:
            if not isinstance(s, ConditionalLoRALinear):
                continue
            s.cl_memory = owner.cl_memory
            s.cl_rad = owner.cl_rad
            s.cl_gmm = owner.cl_gmm  # same aliasing as cl_memory: owner fits, siblings read
            s.jl_P = owner.jl_P  # siblings see identical input -> same projection (None if JL off)
            s.is_disabled = owner.is_disabled  # same aliasing as cl_memory: only the owner appends/writes, siblings read the same per-phase list
            s.is_cl_memory_owner = False

    for module in model.modules():
        attn = getattr(module, "self_attn", None)
        if attn is not None and hasattr(attn, "q_proj"):
            link(attn.q_proj, [getattr(attn, n, None) for n in ("k_proj", "v_proj")])
        mlp = getattr(module, "mlp", None)
        if mlp is not None and hasattr(mlp, "gate_proj"):
            link(mlp.gate_proj, [getattr(mlp, "up_proj", None)])


def add_lora(
    model: nn.Module,
    r: int = 8,
    alpha: float = 16.0,
    cl_rad: Optional[float] = None,
    cl_rad_down: Optional[float] = None,
    gmm_kwargs: Optional[dict] = None,
) -> None:
    """Add one new conditional LoRA to every wrapped linear in the model (grows K
    by one). The newest LoRA is the only trainable one; earlier LoRAs and
    the base stay frozen. The model must already be wrapped via :func:`apply_conditional_lora_wrapper`.

    ``cl_rad`` is the ball radius for all projections; ``cl_rad_down`` (if given) overrides it for
    down_proj only -- whose input dim is much larger (intermediate_size), so the same radius covers
    far less volume there and memory explodes. Tune cl_rad_down separately to control that.

    If calibrate_cl_rad has been run beforehand, each owner module carries a ``_calib_rad``
    attribute that overrides the global cl_rad / cl_rad_down for that specific layer.

    ``gmm_kwargs`` ({'pos_kwargs': ..., 'neg_kwargs': ...}) configures the GMM backend's classifiers;
    unused when cl_memory_type is "uob"."""
    for name, module in model.named_modules():
        if isinstance(module, ConditionalLoRALinear):
            is_down = name.rsplit(".", 1)[-1] == "down_proj"
            fallback_rad = cl_rad_down if (is_down and cl_rad_down is not None) else cl_rad
            module_rad = getattr(module, "_calib_rad", fallback_rad)
            # A module whose NEGATIVE GMM fit failed can never gate: the negative is fitted once (phase 0)
            # and never refitted, so there is no density ratio for any phase. Its new phases are therefore
            # disabled (and frozen) on arrival. Set by cl_memory.fit_layer_gmms; absent on the uob backend
            # and before any fit, where it defaults to False.
            neg_failed = getattr(module, "_neg_fit_failed", False)
            module.add_lora(r=r, alpha=alpha, cl_rad=module_rad, gmm_kwargs=gmm_kwargs,
                            is_disabled=neg_failed)

def set_cl_flag(model: nn.Module, name: str, value) -> None:
    """Set a model-level cl flag (DDP-safe)"""
    inner = model.module if hasattr(model, "module") else model
    setattr(inner, name, value)


def load_cl_rad_calibration(model: nn.Module, calib: dict) -> None:
    """Set the per-layer-module cl_rad on each ConditionalLoRALinear owner from a calibration dict.
    Format: {"layer_<i>": {<module_type>: {"r": <float|null>, "ratio": <float|null>}}}, loaded
    directly from the calib file. Call before add_lora(), which picks up _calib_rad automatically.
    Non-owners (k/v/up_proj) aren't listed in the calib and inherit their owner's setting at link time.

    OBSOLETE: calibration is no longer used (config.calibrate_r is False and calib_rad_path is only built
    for the 'uob' backend). A null r now records _calib_disabled rather than writing is_disabled, which is
    per-phase (one entry per adapter) and written only by GMM fit failures -- see ConditionalLoRALinear."""
    for name, module in model.named_modules():
        if not isinstance(module, ConditionalLoRALinear):
            continue
        parts = name.split(".")
        layer_idx = int(parts[parts.index("layers") + 1])
        mod_type  = parts[-1]
        entry = calib.get(f"layer_{layer_idx}", {}).get(mod_type)
        if entry is None:
            continue  # not calibrated (e.g. a non-owner)
        if entry["r"] is None:
            module.is_disabled = True  # null r -> disable this module's LoRA
        else:
            module._calib_rad = float(entry["r"])
            if entry.get("ratio") is not None:  # expected compression (drop) rate this r was calibrated for
                module._calib_compression_ratio = float(entry["ratio"])

def get_cl_flag(model: nn.Module, name: str, default=None):
    """Read a model-level cl flag (DDP-safe)."""
    inner = model.module if hasattr(model, "module") else model
    return getattr(inner, name, default)

def set_cl_accum_state(model: nn.Module, is_on: bool) -> None:
    """Set the accum state on the model-level (single source of truth) and on the layer level."""
    set_cl_flag(model, "is_cl_accum", is_on)
    for module in model.modules():
        if isinstance(module, ConditionalLoRALinear):
            module.is_cl_accum = is_on

def get_cl_accum_state(model: nn.Module) -> bool:
    return get_cl_flag(model, "is_cl_accum", False)

def set_cl_accum_on(model: nn.Module) -> None:
    """Start buffering forward inputs for cl_memory. Call alongside `model.train()`."""
    set_cl_accum_state(model, True)

def set_cl_accum_off(model: nn.Module) -> None:
    """Stop buffering forward inputs for cl_memory. Call before eval."""
    set_cl_accum_state(model, False)

def update_cl_memory(model: nn.Module) -> None:
    """Flush each wrapped linear's buffered inputs into its accumulating LoRA's
    ``cl_memory``. Call once per optimizer step (after ``optimizer.step()``)."""
    from tqdm import tqdm
    wrapped = [m for m in model.modules() if isinstance(m, ConditionalLoRALinear)]
    for module in tqdm(wrapped, desc="update_cl_memory", leave=False):
        module.update_cl_memory()


def flush_cl_memory(model: nn.Module) -> None:
    """Empty every wrapped linear's accumulating LoRA `cl_memory` (and pending buffer), so the ball
    cover is rebuilt from scratch. Only the currently-training LoRA is cleared; frozen (earlier-task)
    LoRAs keep their memory. Call at the start of an epoch (e.g. per-epoch cl_memory flushing)."""
    for module in model.modules():
        if isinstance(module, ConditionalLoRALinear):
            module.flush_cl_memory()


def cl_memory_breakdown(model: nn.Module) -> dict:
    """cl_memory MB broken down two ways: by layer index and by module type. Only owners
    hold a real buffer (siblings alias it), so each shared buffer is counted once, under its
    owner's name (e.g. the q/k/v buffer counts as 'q_proj', gate/up as 'gate_proj').
    Returns {'per_layer': {layer_idx: MB}, 'per_type': {module_type: MB}, 'total_mb': MB}."""
    per_layer, per_type = {}, {}
    total_bytes = 0
    inner = model.module if hasattr(model, "module") else model
    for name, module in inner.named_modules():
        if not (isinstance(module, ConditionalLoRALinear) and module.is_cl_memory_owner):
            continue
        mtype = name.rsplit(".", 1)[-1]                          # e.g. "down_proj"
        parts = name.split(".")                                   # ...layers.<i>.<...>
        if mtype not in LORA_DEFAULT_TARGET_MODULES or "layers" not in parts:
            continue                                             # unexpected naming -> skip entirely
        mb = sum(m.numel() * m.element_size() for m in module.cl_memory) / 1024**2
        total_bytes += mb
        per_type[mtype] = per_type.get(mtype, 0.0) + mb
        layer = int(parts[parts.index("layers") + 1])
        per_layer[layer] = per_layer.get(layer, 0.0) + mb
    return {"per_layer": per_layer, "per_type": per_type, "total_mb": total_bytes}


def report_cl_memory(model: nn.Module) -> None:
    """Print the memory held by the CL buffers: cl_memory and the pending_x buffer, total and
    average per layer, plus the per-layer and per-module-type cl_memory breakdown."""
    total_bytes, pending_bytes, num_mats = 0, 0, 0
    for module in model.modules():
        if isinstance(module, ConditionalLoRALinear):
            num_mats += 1
            if not module.is_cl_memory_owner: # count each buffer once (owner's)
                continue
            total_bytes += sum(m.numel() * m.element_size() for m in module.cl_memory)
            pending_bytes += sum(p.numel() * p.element_size() for p in module._pending_x)
    num_layers = num_mats // len(LORA_DEFAULT_TARGET_MODULES)  # 7 wrapped matrices per layer
    total_mb = total_bytes / 1024**2
    pending_mb = pending_bytes / 1024**2
    avg_mb = total_mb / max(1, num_layers)
    avg_pending_mb = pending_mb / max(1, num_layers)
    print(f"[cl_memory] total: {total_mb:.1f} MB over {num_layers} layers, avg {avg_mb:.2f} MB/layer | "
          f"pending_x: {pending_mb:.1f} MB total, avg {avg_pending_mb:.2f} MB/layer")
    bd = cl_memory_breakdown(model)
    by_type = " ".join(f"{t}={mb:.1f}" for t, mb in sorted(bd["per_type"].items()))
    print(f"[cl_memory] by module type (MB): {by_type}")
    by_layer = " ".join(f"L{l}={mb:.1f}" for l, mb in sorted(bd["per_layer"].items()))
    print(f"[cl_memory] by layer (MB): {by_layer}")


def report_compaction(model: nn.Module) -> None:
    s_seen = s_kept = t_seen = t_kept = 0
    calib_ratios = []  # expected drop rate per active owner (from the r calibration), if present
    for module in model.modules():
        if isinstance(module, ConditionalLoRALinear):
            s_seen += module.compact_step_seen
            s_kept += module.compact_step_kept
            t_seen += module.compact_total_seen
            t_kept += module.compact_total_kept
            if module.is_cl_memory_owner and not module.is_disabled and hasattr(module, "_calib_compression_ratio"):
                calib_ratios.append(module._calib_compression_ratio)
    step_drop = 1 - s_kept / s_seen if s_seen else 0.0
    total_drop = 1 - t_kept / t_seen if t_seen else 0.0
    # expected drop = mean calibrated compression ratio over active owners (the r's were tuned for it)
    expected = f" (expected: {sum(calib_ratios) / len(calib_ratios):.3%})" if calib_ratios else ""
    print(f"[compaction] step: kept {s_kept}/{s_seen} (dropped {step_drop:.3%}{expected}) | "
          f"total: kept {t_kept}/{t_seen} (dropped {total_drop:.3%}{expected})")


def save_cl_state(model: nn.Module, path: str) -> None:
    """Save the full conditional-LoRA state (all adapters + their cl_memory) so a fully trained model
    can be reloaded later (e.g. via config.load_cl_state_path). Call on rank 0.
    Not saved: the frozen base weights (reloaded from config.model_name at wrap time).
    Note: this is for external use by the user. See cl_memory.save/load_gmms for finer functionality like handling specific 
    gmms during a run (e.g. save/load only the neg)."""
    inner = model.module if hasattr(model, "module") else model
    modules = {}
    for name, module in inner.named_modules():
        if not isinstance(module, ConditionalLoRALinear):
            continue
        modules[name] = {
            "lora_A": [p.detach().cpu() for p in module.lora_A],
            "lora_B": [p.detach().cpu() for p in module.lora_B],
            "scalings": list(module.scalings),
            "cl_rad": list(module.cl_rad),
            "is_disabled": list(module.is_disabled),  # per-phase: one entry per adapter
            "jl_P": module.jl_P.detach().cpu() if module.jl_P is not None else None,
            "cl_memory_type": module.cl_memory_type,
            # Module-level and permanent: without it a reloaded model would append an enabled, trainable
            # phase to a module whose negative GMM never fitted (see add_lora).
            "neg_fit_failed": getattr(module, "_neg_fit_failed", False),
            # Only owners hold real cl_memory / cl_gmm (siblings alias them); non-owners save empty lists.
            "cl_memory": [m.detach().cpu() for m in module.cl_memory] if module.is_cl_memory_owner else [],
            "cl_gmm": [g.state_dict() for g in module.cl_gmm] if module.is_cl_memory_owner else [],
        }
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    torch.save(modules, path)


def load_cl_state(model: nn.Module, path: str) -> None:
    """Load a state saved by save_cl_state into a fresh base model (K=0, no adapters yet).
    Re-adds each saved LoRA, then copies back the adapter weights, jl_P and cl_memory.
    Note: this is for external use by the user. See cl_memory.save/load_gmms for finer functionality like handling specific 
    gmms during a run (e.g. save/load only the neg)."""
    inner = model.module if hasattr(model, "module") else model
    modules = torch.load(path, map_location="cpu", weights_only=False)
    for name, module in inner.named_modules():
        if not isinstance(module, ConditionalLoRALinear):
            continue
        saved = modules[name]
        module.cl_memory_type = saved.get("cl_memory_type", "uob")
        # Permanent module-level verdict, so a phase added after this reload is disabled on arrival rather
        # than appended enabled and trainable to a module that can never gate. Absent in older files.
        module._neg_fit_failed = saved.get("neg_fit_failed", False)
        module.jl_P = saved["jl_P"].to(module.base.weight.device, module.base.weight.dtype) if saved["jl_P"] is not None else None
        for i in range(len(saved["lora_A"])):
            # alpha unused: only feeds scaling=alpha/r, restored below. gmm_kwargs come from the saved classifier, whose fitted params are copied back once the LoRAs exist.
            gmm_kwargs = {k: saved["cl_gmm"][i][k] for k in ("pos_kwargs", "neg_kwargs")} if saved["cl_gmm"] else None
            module.add_lora(r=saved["lora_A"][i].shape[0], alpha=0.0, cl_rad=saved["cl_rad"][i], gmm_kwargs=gmm_kwargs)
        module.scalings = list(saved["scalings"])  # scaling (=alpha/r) fully captures alpha; overwrites the alpha=0 placeholder
        # Restored here rather than before the loop above: each add_lora appends its own entry, so assigning
        # earlier would leave the saved entries followed by one False per adapter. Written in place so the
        # siblings aliasing the owner's list keep pointing at it. Files saved before is_disabled became
        # per-phase hold a single bool -- those runs were single-phase, so it becomes a one-element list.
        saved_disabled = saved["is_disabled"]
        if not isinstance(saved_disabled, list):
            saved_disabled = [bool(saved_disabled)]
        module.is_disabled[:] = saved_disabled
        dev, dtype = module.base.weight.device, module.base.weight.dtype
        for i, (A, B) in enumerate(zip(saved["lora_A"], saved["lora_B"])):
            module.lora_A[i].data = A.to(dev, dtype)
            module.lora_B[i].data = B.to(dev, dtype)
        if module.is_cl_memory_owner:  # write in place so aliasing siblings keep pointing at this list
            module.cl_memory[:] = [m.to(dev, torch.bfloat16) for m in saved["cl_memory"]]
            for gmm_clf, gmm_state in zip(module.cl_gmm, saved["cl_gmm"]):
                gmm_clf.load_state_dict(gmm_state)


class Qwen2MLP(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.config = config
        self.hidden_size = config.hidden_size
        self.intermediate_size = config.intermediate_size
        self.gate_proj = nn.Linear(self.hidden_size, self.intermediate_size, bias=False)
        self.up_proj = nn.Linear(self.hidden_size, self.intermediate_size, bias=False)
        self.down_proj = nn.Linear(self.intermediate_size, self.hidden_size, bias=False)
        self.act_fn = ACT2FN[config.hidden_act]

    def forward(self, x, token_pad_mask: Optional[torch.Tensor] = None):
        h = self.act_fn(_proj(self.gate_proj, x, token_pad_mask)) * _proj(self.up_proj, x, token_pad_mask)
        down_proj = _proj(self.down_proj, h, token_pad_mask)
        return down_proj


def rotate_half(x):
    """Rotates half the hidden dims of the input."""
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def apply_rotary_pos_emb(q, k, cos, sin, position_ids=None, unsqueeze_dim=1):
    """Applies Rotary Position Embedding to the query and key tensors.

    Args:
        q (`torch.Tensor`): The query tensor.
        k (`torch.Tensor`): The key tensor.
        cos (`torch.Tensor`): The cosine part of the rotary embedding.
        sin (`torch.Tensor`): The sine part of the rotary embedding.
        position_ids (`torch.Tensor`, *optional*):
            Deprecated and unused.
        unsqueeze_dim (`int`, *optional*, defaults to 1):
            The 'unsqueeze_dim' argument specifies the dimension along which to unsqueeze cos[position_ids] and
            sin[position_ids] so that they can be properly broadcasted to the dimensions of q and k. For example, note
            that cos[position_ids] and sin[position_ids] have the shape [batch_size, seq_len, head_dim]. Then, if q and
            k have the shape [batch_size, heads, seq_len, head_dim], then setting unsqueeze_dim=1 makes
            cos[position_ids] and sin[position_ids] broadcastable to the shapes of q and k. Similarly, if q and k have
            the shape [batch_size, seq_len, heads, head_dim], then set unsqueeze_dim=2.
    Returns:
        `tuple(torch.Tensor)` comprising of the query and key tensors rotated using the Rotary Position Embedding.
    """
    cos = cos.unsqueeze(unsqueeze_dim)
    sin = sin.unsqueeze(unsqueeze_dim)
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    return q_embed, k_embed


def repeat_kv(hidden_states: torch.Tensor, n_rep: int) -> torch.Tensor:
    """
    This is the equivalent of torch.repeat_interleave(x, dim=1, repeats=n_rep). The hidden states go from (batch,
    num_key_value_heads, seqlen, head_dim) to (batch, num_attention_heads, seqlen, head_dim)
    """
    batch, num_key_value_heads, slen, head_dim = hidden_states.shape
    if n_rep == 1:
        return hidden_states
    hidden_states = hidden_states[:, :, None, :, :].expand(batch, num_key_value_heads, n_rep, slen, head_dim)
    return hidden_states.reshape(batch, num_key_value_heads * n_rep, slen, head_dim)


def eager_attention_forward(
    module: nn.Module,
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    attention_mask: Optional[torch.Tensor],
    scaling: float,
    dropout: float = 0.0,
    **kwargs: Unpack[TransformersKwargs],
):
    key_states = repeat_kv(key, module.num_key_value_groups)
    value_states = repeat_kv(value, module.num_key_value_groups)

    attn_weights = torch.matmul(query, key_states.transpose(2, 3)) * scaling
    if attention_mask is not None:
        causal_mask = attention_mask[:, :, :, : key_states.shape[-2]]
        attn_weights = attn_weights + causal_mask

    attn_weights = nn.functional.softmax(attn_weights, dim=-1, dtype=torch.float32).to(query.dtype)
    attn_weights = nn.functional.dropout(attn_weights, p=dropout, training=module.training)
    attn_output = torch.matmul(attn_weights, value_states)
    attn_output = attn_output.transpose(1, 2).contiguous()

    return attn_output, attn_weights


class Qwen2Attention(nn.Module):
    """Multi-headed attention from 'Attention Is All You Need' paper"""

    def __init__(self, config: Qwen2Config, layer_idx: int):
        super().__init__()
        self.config = config
        self.layer_idx = layer_idx
        self.head_dim = getattr(config, "head_dim", config.hidden_size // config.num_attention_heads)
        self.num_key_value_groups = config.num_attention_heads // config.num_key_value_heads
        self.scaling = self.head_dim**-0.5
        self.attention_dropout = config.attention_dropout
        self.is_causal = True
        self.q_proj = nn.Linear(config.hidden_size, config.num_attention_heads * self.head_dim, bias=True)
        self.k_proj = nn.Linear(config.hidden_size, config.num_key_value_heads * self.head_dim, bias=True)
        self.v_proj = nn.Linear(config.hidden_size, config.num_key_value_heads * self.head_dim, bias=True)
        self.o_proj = nn.Linear(config.num_attention_heads * self.head_dim, config.hidden_size, bias=False)
        self.sliding_window = config.sliding_window if config.layer_types[layer_idx] == "sliding_attention" else None

    @deprecate_kwarg("past_key_value", new_name="past_key_values", version="4.58")
    def forward(
        self,
        hidden_states: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor],
        attention_mask: Optional[torch.Tensor],
        past_key_values: Optional[Cache] = None,
        cache_position: Optional[torch.LongTensor] = None,
        token_pad_mask: Optional[torch.Tensor] = None,
        **kwargs: Unpack[FlashAttentionKwargs],
    ) -> tuple[torch.Tensor, Optional[torch.Tensor]]:
        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)

        query_states = _proj(self.q_proj, hidden_states, token_pad_mask).view(hidden_shape).transpose(1, 2)
        key_states = _proj(self.k_proj, hidden_states, token_pad_mask).view(hidden_shape).transpose(1, 2)
        value_states = _proj(self.v_proj, hidden_states, token_pad_mask).view(hidden_shape).transpose(1, 2)

        cos, sin = position_embeddings
        query_states, key_states = apply_rotary_pos_emb(query_states, key_states, cos, sin)

        if past_key_values is not None:
            # sin and cos are specific to RoPE models; cache_position needed for the static cache
            cache_kwargs = {"sin": sin, "cos": cos, "cache_position": cache_position}
            key_states, value_states = past_key_values.update(key_states, value_states, self.layer_idx, cache_kwargs)

        attention_interface: Callable = eager_attention_forward
        if self.config._attn_implementation != "eager":
            attention_interface = ALL_ATTENTION_FUNCTIONS[self.config._attn_implementation]

        attn_output, attn_weights = attention_interface(
            self,
            query_states,
            key_states,
            value_states,
            attention_mask,
            dropout=0.0 if not self.training else self.attention_dropout,
            scaling=self.scaling,
            sliding_window=self.sliding_window,  # main diff with Llama
            **kwargs,
        )

        attn_output = attn_output.reshape(*input_shape, -1).contiguous()
        attn_output = _proj(self.o_proj, attn_output, token_pad_mask)
        return attn_output, attn_weights


@use_kernel_forward_from_hub("RMSNorm")
class Qwen2RMSNorm(nn.Module):
    def __init__(self, hidden_size, eps: float = 1e-6) -> None:
        """
        Qwen2RMSNorm is equivalent to T5LayerNorm
        """
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.variance_epsilon = eps

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        input_dtype = hidden_states.dtype
        hidden_states = hidden_states.to(torch.float32)
        variance = hidden_states.pow(2).mean(-1, keepdim=True)
        hidden_states = hidden_states * torch.rsqrt(variance + self.variance_epsilon)
        return self.weight * hidden_states.to(input_dtype)

    def extra_repr(self):
        return f"{tuple(self.weight.shape)}, eps={self.variance_epsilon}"


class Qwen2DecoderLayer(GradientCheckpointingLayer):
    def __init__(self, config: Qwen2Config, layer_idx: int):
        super().__init__()
        self.hidden_size = config.hidden_size

        self.self_attn = Qwen2Attention(config=config, layer_idx=layer_idx)

        self.mlp = Qwen2MLP(config)
        self.input_layernorm = Qwen2RMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.post_attention_layernorm = Qwen2RMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.attention_type = config.layer_types[layer_idx]

    @deprecate_kwarg("past_key_value", new_name="past_key_values", version="4.58")
    def forward(
        self,
        hidden_states: torch.Tensor,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[Cache] = None,
        use_cache: Optional[bool] = False,
        cache_position: Optional[torch.LongTensor] = None,
        position_embeddings: Optional[tuple[torch.Tensor, torch.Tensor]] = None,  # necessary, but kept here for BC
        token_pad_mask: Optional[torch.Tensor] = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> torch.Tensor:
        residual = hidden_states
        hidden_states = self.input_layernorm(hidden_states)
        # Self Attention
        hidden_states, _ = self.self_attn(
            hidden_states=hidden_states,
            attention_mask=attention_mask,
            position_ids=position_ids,
            past_key_values=past_key_values,
            use_cache=use_cache,
            cache_position=cache_position,
            position_embeddings=position_embeddings,
            token_pad_mask=token_pad_mask,
            **kwargs,
        )
        hidden_states = residual + hidden_states

        # Fully Connected
        residual = hidden_states
        hidden_states = self.post_attention_layernorm(hidden_states)
        hidden_states = self.mlp(hidden_states, token_pad_mask)
        hidden_states = residual + hidden_states
        return hidden_states


